-- Daily challenges for 2026-11-14: two new themes, 365 to-dos each (added on 2026-11-21 to fill a missed day).
-- Generated by tools/challenges_sql.py giving-thoughtful-gifts doing-one-thing-at-a-time. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('giving-thoughtful-gifts', 'Giving Thoughtful Gifts', 'For anyone who wants giving to feel less stressful and more personal. Each day is one small way to notice what people love, give within your budget, and offer time, help or words that mean as much as anything wrapped.', 'Kindness', 365, array['Relationships', 'Values']::text[], 1, '2026-11-14T17:00:00+00:00'::timestamptz),
  ('doing-one-thing-at-a-time', 'Doing One Thing at a Time', 'For anyone whose attention is pulled in five directions at once. Each day is one small way to give a single task, conversation or moment your full attention, from washing a dish to reading a page, and let the rest wait.', 'Focus', 365, array['Mindfulness', 'Stress']::text[], 1, '2026-11-14T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('giving-thoughtful-gifts', 'doing-one-thing-at-a-time');

